INSERT INTO package_questions (package_id, question_json, hash_logico, order_index, status) VALUES
('a0006a29-3d79-4b83-8348-64144b0da701', '{"enunciado":"A ''Lei de Poiseuille'' descreve os fatores que determinam o fluxo laminar através de um tubo (como uma cânula venosa ou tubo traqueal). De acordo com esta lei, qual alteração tem o maior impacto no aumento do fluxo de fluidos?","options":{"a":"Dobrar a pressão de infusão.","b":"Diminuir a viscosidade do fluido pela metade.","c":"Dobrar o raio do cateter.","d":"Dobrar o comprimento do cateter.","e":"Aumentar a temperatura do fluido."},"answer":"c","rationale":"O fluxo é diretamente proporcional à quarta potência do raio (r⁴). Dobrar o raio aumenta o fluxo em 16 vezes.","option_rationales":{"a":"Errada. Aumentaria o fluxo apenas 2 vezes.","b":"Errada. Aumentaria o fluxo apenas 2 vezes.","c":"Correta. Física aplicada à anestesia.","d":"Errada. Reduziria o fluxo pela metade.","e":"Errada."},"difficulty":"Média","tags":["Anestesiologia","Física","Acesso Vascular"]}', 'cf6fd76301e3c6653a89acd361f2bf17', 108, 'draft'),
('a0006a29-3d79-4b83-8348-64144b0da701', '{"enunciado":"O ''Efeito Bohr'' descreve a mudança na afinidade da hemoglobina pelo oxigênio em resposta a alterações químicas no sangue. Qual das seguintes alterações desloca a curva de dissociação da oxiemoglobina para a DIREITA (facilitando a entrega de O2 aos tecidos)?","options":{"a":"Diminuição da temperatura (hipotermia).","b":"Aumento do pH (alcalose).","c":"Diminuição do 2,3-DPG.","d":"Aumento da PaCO2 (acidose respiratória).","e":"Presença de Carboxihemoglobina."},"answer":"d","rationale":"Aumento de CO2, H+ (queda de pH), temperatura e 2,3-DPG deslocam a curva para a direita.","option_rationales":{"a":"Errada. Desloca para a esquerda.","b":"Errada. Desloca para a esquerda.","c":"Errada. Desloca para a esquerda.","d":"Correta. Fisiologia respiratória e transporte de gases.","e":"Errada. Desloca para a esquerda."},"difficulty":"Média","tags":["Anestesiologia","Fisiologia","Transporte de O2"]}', '4e1915162e66d19aa0d1d19241b6c1d9', 109, 'draft'),
('a0006a29-3d79-4b83-8348-64144b0da701', '{"enunciado":"A ''Hipertermia Maligna'' é uma síndrome farmacogenética desencadeada por anestésicos inalatórios voláteis ou succinilcolina. Qual o defeito fisiopatológico central desta condição?","options":{"a":"Bloqueio irreversível dos receptores nicotínicos.","b":"Liberação excessiva e descontrolada de cálcio do retículo sarcoplasmático através do receptor ryanodina (RYR1).","c":"Falha na recaptação de acetilcolina na fenda sináptica.","d":"Destruição autoimune da placa motora.","e":"Depleção súbita de ATP muscular."},"answer":"b","rationale":"O cálcio intracelular elevado causa contração muscular sustentada, hipermetabolismo, produção de calor e CO2.","option_rationales":{"a":"Errada.","b":"Correta. Fisiopatologia e emergências anestésicas.","c":"Errada.","d":"Errada.","e":"Errada. A depleção é consequência, não causa inicial."},"difficulty":"Média","tags":["Anestesiologia","Complicações","Hipertermia Maligna"]}', '58419f3c37faf663cd1381fbf1042617', 110, 'draft'),
('a0006a29-3d79-4b83-8348-64144b0da701', '{"enunciado":"Qual o sinal clínico MAIS PRECOCE e sensível de uma crise de Hipertermia Maligna em um paciente sob anestesia geral e ventilação controlada?","options":{"a":"Hipertermia (aumento da temperatura corporal).","b":"Rigidez muscular generalizada.","c":"Aumento súbito e persistente do EtCO2 (hipercapnia) apesar do aumento da ventilação.","d":"Arritmias cardíacas.","e":"Mioglobinúria (urina cor de ''coca-cola'')."},"answer":"c","rationale":"O aumento da produção de CO2 pelo metabolismo muscular acelerado precede a febre, que é um sinal tardio.","option_rationales":{"a":"Errada. Sinal tardio.","b":"Errada. Comum, mas o EtCO2 costuma subir antes.","c":"Correta. Diagnóstico de emergências.","d":"Errada.","e":"Errada. Sinal muito tardio."},"difficulty":"Média","tags":["Anestesiologia","Complicações","Monitorização"]}', '6dc6d52158123aad49937832b79a87ce', 111, 'draft'),
('a0006a29-3d79-4b83-8348-64144b0da701', '{"enunciado":"Qual a medicação específica no tratamento da Hipertermia Maligna e qual seu mecanismo de ação?","options":{"a":"Atropina; bloqueia o vago.","b":"Dantrolene; inibe a liberação de cálcio do retículo sarcoplasmático.","c":"Insulina e Glicose; tratam a hipercalemia.","d":"Gluconato de Cálcio; estabiliza a membrana miocárdica.","e":"Bicarbonato de Sódio; trata a acidose."},"answer":"b","rationale":"O dantrolene liga-se ao receptor RYR1, reduzindo a concentração de cálcio no citoplasma do miócito.","option_rationales":{"a":"Errada.","b":"Correta. Terapêutica em anestesia.","c":"Errada. São medidas de suporte.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anestesiologia","Farmacologia","Hipertermia Maligna"]}', 'e95e897fe8e3aec7bb7ca744b8fe7b45', 112, 'draft'),
('a0006a29-3d79-4b83-8348-64144b0da701', '{"enunciado":"O ''Nervo Laríngeo Recorrente'' esquerdo tem um trajeto intratorácico mais longo que o direito. Em torno de qual estrutura vascular ele realiza a curva (loop) antes de subir para a laringe?","options":{"a":"Artéria Braquiocefálica.","b":"Artéria Subclávia Direita.","c":"Arco da Aorta (atrás do ligamento arterioso).","d":"Veia Cava Superior.","e":"Artéria Carótida Comum."},"answer":"c","rationale":"Devido a este trajeto, cirurgias toráxicas ou aneurismas de aorta podem causar rouquidão por paralisia de corda vocal esquerda.","option_rationales":{"a":"Errada.","b":"Errada. (Trajeto do recorrente direito).","c":"Correta. Anatomia torácica e via aérea.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anestesiologia","Anatomia","Via Aérea"]}', 'bc88fc10eda094e7aa820620ef6f9c8f', 113, 'draft'),
('a0006a29-3d79-4b83-8348-64144b0da701', '{"enunciado":"A ''Anatomia do Espaço Epidural'' inclui o ligamento amarelo (ligamentum flavum). Qual a principal característica biomecânica deste ligamento que auxilia o anestesista a identificar a entrada no espaço epidural por ''perda de resistência''?","options":{"a":"É extremamente fino e frágil.","b":"Possui alta proporção de fibras elástiças, oferecendo uma resistência firme e súbita.","c":"É sempre ossificado em idosos.","d":"É uma estrutura flácida.","e":"Não oferece resistência à agulha."},"answer":"b","rationale":"A sensação de ''clique'' ou queda de resistência ocorre ao atravessar a densidade do ligamento amarelo para o espaço epidural (que tem pressão negativa ou baixa resistência).","option_rationales":{"a":"Errada.","b":"Correta. Anatomia aplicada à anestesia regional.","c":"Errada. Pode haver calcificação, mas não é regra.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anestesiologia","Regional","Anatomia"]}', 'bdcd201345c1b0c58ec788c04c41c722', 114, 'draft'),
('a0006a29-3d79-4b83-8348-64144b0da701', '{"enunciado":"Em relação à ''Inervação Simpática'' do coração, quais níveis medulares (segmentos espinais) são responsáveis pelas fibras cardioaceleradoras?","options":{"a":"C1 a C4.","b":"T1 a T4.","c":"T5 a T10.","d":"L1 a L2.","e":"S2 a S4."},"answer":"b","rationale":"Um bloqueio espinal (raqui ou epidural) que atinja níveis torácicos altos (acima de T4) pode causar bradicardia severa por bloqueio destas fibras.","option_rationales":{"a":"Errada.","b":"Correta. Fisiologia do sistema nervoso autônomo.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anestesiologia","Fisiologia","Regional"]}', 'f75101404425aabb9bf7623d38ea8b5b', 115, 'draft'),
('a0006a29-3d79-4b83-8348-64144b0da701', '{"enunciado":"A ''Bupivacaína'' apresenta uma toxicidade sistêmica (LAST) característica. Qual o principal órgão afetado e qual a alteração eletrocardiográfica típica?","options":{"a":"Fígado; icterícia imediata.","b":"Cérebro; convulsões seguidas de coma.","c":"Coração; arritmias ventriculares graves e alargamento do complexo QRS (bloqueio de canais de sódio).","d":"Rim; anúria.","e":"Pulmão; broncoespasmo."},"answer":"c","rationale":"A bupivacaína é cardiotóxica devido à sua forte afinidade e dissociação lenta dos canais de sódio cardíacos (reentrada).","option_rationales":{"a":"Errada.","b":"Errada. Comum a todos AL, mas a bupivacaína destaca-se pela cardiotoxicidade.","c":"Correta. Farmacologia e complicações.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anestesiologia","Farmacologia","Toxicidade"]}', 'f2cb6961d38e9ecca875b0937966c8bf', 116, 'draft'),
('a0006a29-3d79-4b83-8348-64144b0da701', '{"enunciado":"Qual emulsão lipídica é utilizada como ''Antídoto'' na intoxicação sistêmica por anestésicos locais (LAST)?","options":{"a":"Liposyn I.","b":"Intralipid 20%.","c":"Propofol 1%.","d":"Omegaven.","e":"Solução salina hipertônica."},"answer":"b","rationale":"A emulsão lipídica atua como um ''sumidouro'' (lipid sink), sequestrando o anestésico lipossolúvel do plasma.","option_rationales":{"a":"Errada.","b":"Correta. Protocolo de segurança em anestesia.","c":"Errada. O propofol contém lipídios, mas a concentração de droga pioraria a depressão miocárdica.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anestesiologia","Farmacologia","Toxicidade","LAST"]}', '8093bf0d1d280f1eb89ae838d7c6f30e', 117, 'draft'),
('a0006a29-3d79-4b83-8348-64144b0da701', '{"enunciado":"Sobre o ''Nervo Ulnar'', em qual localização anatômica ele é mais suscetível à lesão por compressão durante o posicionamento cirúrgico inadequado?","options":{"a":"No sulco bicipital lateral.","b":"No canal de Guyon (pulso).","c":"No sulco do nervo ulnar (atrás do epicôndilo medial do úmero).","d":"Na axila.","e":"No forame intervertebral C8."},"answer":"c","rationale":"Esta é a neuropatia perioperatória mais comum. O nervo é superficial e fixo no cotovelo.","option_rationales":{"a":"Errada.","b":"Errada.","c":"Correta. Complicações de posicionamento.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anestesiologia","Posicionamento","Complicações"]}', 'b8dfec63a7ef891cec35a1e325e6d4d1', 118, 'draft'),
('a0006a29-3d79-4b83-8348-64144b0da701', '{"enunciated":"A ''Capacidade Residual Funcional'' (CRF) é a soma de quais volumes pulmonares?","options":{"a":"Volume Corrente + Volume de Reserva Inspiratório.","b":"Volume de Reserva Expiratório + Volume Residual.","c":"Capacidade Vital + Volume Residual.","d":"Volume Corrente + Volume Residual.","e":"Capacidade Inspiratória + Capacidade Vital."},"answer":"b","rationale":"A CRF representa o ar que permanece nos pulmões após uma expiração normal, servindo como reserva de oxigênio durante a apneia.","option_rationales":{"a":"Errada.","b":"Correta. Fisiologia respiratória fundamental.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anestesiologia","Fisiologia Respiratória"]}', 'no-text-hash', 119, 'draft'),
('a0006a29-3d79-4b83-8348-64144b0da701', '{"enunciado":"A ''Pressão Parcial de CO2 no Sangue Arterial'' (PaCO2) é o principal determinante do Fluxo Sanguíneo Cerebral (FSC). Como o FSC responde a uma redução da PaCO2 de 40 mmHg para 20 mmHg (Hipocapnia)?","options":{"a":"O FSC aumenta drasticamente.","b":"O FSC permanece inalterado.","c":"O FSC diminui por vasoconstrição cerebral.","d":"O FSC diminui apenas por queda na pressão arterial.","e":"O FSC aumenta para compensar a falta de CO2."},"answer":"c","rationale":"A hipocapnia causa vasoconstrição precoce, sendo usada terapeuticamente para reduzir agudamente a PIC em crises de herniação.","option_rationales":{"a":"Errada. Isso ocorreria com hipercapnia.","b":"Errada.","c":"Correta. Fisiologia do sistema nervoso central.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anestesiologia","Fisiologia","SNC"]}', 'f31a586c874e88b94e3f13ba6b1fa70f', 120, 'draft'),
('a0006a29-3d79-4b83-8348-64144b0da701', '{"enunciado":"Qual a ''Dose Tóxica'' máxima recomendada para a Lidocaína SEM vasoconstritor em um adulto saudável?","options":{"a":"3 mg/kg.","b":"5 mg/kg.","c":"7 mg/kg.","d":"10 mg/kg.","e":"15 mg/kg."},"answer":"b","rationale":"Valores clássicos: 5 mg/kg sem adrenalina e 7 mg/kg com adrenalina.","option_rationales":{"a":"Errada. (Bupivacaína é 2-3 mg/kg).","b":"Correta. Farmacologia de anestésicos locais.","c":"Errada. (Com vasoconstritor).","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anestesiologia","Farmacologia","Doses"]}', '80886b4aee15d07d5f5cced10cd7317e', 121, 'draft'),
('a0006a29-3d79-4b83-8348-64144b0da701', '{"enunciado":"A ''Albumina'' é a principal proteína plasmática responsável por qual pressão no compartimento vascular?","options":{"a":"Pressão Hidrostática.","b":"Pressão Osmótica Coloidosmótica (Oncótica).","c":"Saturação de Oxigênio.","d":"Pressão de vapor.","e":"Pressão transmural."},"answer":"b","rationale":"A pressão oncótica mantém o fluido dentro dos vasos, contrapondo-se à pressão hidrostática (Equação de Starling).","option_rationales":{"a":"Errada. Gerada pela bomba cardíaca.","b":"Correta. Fisiologia cardiovascular e fluidoterapia.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anestesiologia","Fisiologia","Hemodinâmica"]}', '1da4008fc84af5ff7f82d74989b1c062', 122, 'draft');